// js-tiktoken's GPT-2 BPE must produce the same ids as Python's tiktoken for the
// strings in tokenizer.fixtures.json (generated by scripts/make_tokenizer_fixtures.py).
import { describe, expect, it } from 'vitest';
import fixtures from './tokenizer.fixtures.json';
import { EOT, decode, encode } from '../src/tokenizer';

describe('GPT-2 BPE tokenizer', () => {
    it('has fixtures generated from Python tiktoken', () => {
        expect(fixtures.length).toBeGreaterThanOrEqual(20);
    });

    it.each(fixtures.map((f) => [JSON.stringify(f.text).slice(0, 40), f] as const))(
        'matches tiktoken for %s',
        (_name, fixture) => {
            expect(encode(fixture.text)).toEqual(fixture.tokens);
            expect(decode(fixture.tokens)).toBe(fixture.decoded);
        },
    );

    it('encodes a prompt the way sample.py does: EOT, then the text', () => {
        expect([EOT, ...encode('Once upon a time')]).toEqual([50256, 7454, 2402, 257, 640]);
    });

    it('round-trips every fixture', () => {
        for (const fixture of fixtures) expect(decode(encode(fixture.text))).toBe(fixture.decoded);
    });
});
